function toast(message){$('toast').textContent=t(message);$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5500);}
const translateTerrain=message=>t(message);
function refreshMapStatus(){const status=renderer.status(state);$('terrainStatus').textContent=(status.detailFailed?t('詳細地理圖層載入失敗，請重新載入。'):status.detailPending?t('詳細地理圖層尚未載入完成。'):translateTerrain(status.message))+(status.adminMessage?' · '+status.adminMessage:'')+(status.waterMessage?' · '+status.waterMessage:'');$('retryTerrain').hidden=!status.failed;}
function scheduleDraw(){clampCamera();if(!state.interacting&&!historyHolding)historyController?.schedule();captionController?.refresh();if(pendingFrame||!ready)return;pendingFrame=true;requestAnimationFrame(()=>{pendingFrame=false;prepareLegendFonts(state)?.then(scheduleDraw,()=>{});renderer.render(state);refreshViewport();legendEditor?.updateOverlay();analysisController?.refresh();codegenController?.refresh();refreshMapStatus();});}
function syncPageControls(){const page=pageSize(state.settings);$('pageWidth').value=page.widthCm;$('pageHeight').value=page.heightCm;$('aspectPreset').value=pagePreset(state.settings);$('map').style.aspectRatio=String(page.ratio);$('pageHint').textContent=tx('pageHint',{w:page.widthCm,h:page.heightCm});$('exportPageSize').textContent=`（${page.widthCm} × ${page.heightCm} cm）`;for(const option of $('exportWidth').options){const pixels=Number(option.value);option.textContent=tx('dpi',{pixels:pixels.toLocaleString()+' × '+outputSize(state.settings,pixels).height.toLocaleString(),dpi:Math.round(pixels/page.widthCm*2.54)});}try{const output=outputSize(state.settings,Number($('exportWidth').value));$('outputPixels').textContent=tx('output',{w:output.width.toLocaleString(),h:output.height.toLocaleString()});}catch(e){$('outputPixels').textContent=t(e.message);}}
