function refreshLanguage(){refreshRegions();state.language=getLanguage();applyLanguage();syncLegendControls();syncPageControls();refreshValidation();if(state.demo)$('fileLabel').textContent=tx('demoBadge',{n:state.groups.length});const ungrouped=[...$('groupCol').options].find(o=>o.value==='');if(ungrouped)ungrouped.textContent=t('不分組（Point）');renderGroups();updateTable();analysisController?.refresh();codegenController?.refresh();if(ready)refreshMapStatus();$('tooltip').hidden=true;$('toast').hidden=true;if(!busy)$('exportStatus').textContent='';scheduleDraw();}
