function activePoints(){return state.valid.filter(p=>state.selected.has(p.group));}
function updateSites(){const s=state.settings;state.catalog=siteCatalog(state.valid,s);state.sites=withSiteIds(groupSites(activePoints(),s.digits,s.pieMode,s.pies),state.catalog,s.pies);$('recordStat').textContent=state.valid.length.toLocaleString();$('siteStat').textContent=state.sites.length.toLocaleString();$('groupStat').textContent=`${state.selected.size}/${state.groups.length}`;updateTable();analysisController?.refresh();codegenController?.refresh();scheduleDraw();}
function setPanel(name){for(const b of document.querySelectorAll('[data-panel]')){const on=b.dataset.panel===name;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));}for(const n of ['data','style','export'])$('panel-'+n).hidden=n!==name;if(matchMedia('(max-width:800px)').matches)$('panel-'+name).scrollIntoView({behavior:'smooth',block:'start'});}
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>setPanel(b.dataset.panel)));
function installData(raw,filename,demo=false){const columns=detectColumns(raw.headers);if(!columns.lon)columns.lon=raw.headers[0];if(!columns.lat)columns.lat=raw.headers[1]||'';state.raw=raw;state.filename=filename;state.columns=columns;state.demo=demo;state.page=0;
 for(const [id,key] of [['lonCol','lon'],['latCol','lat'],['groupCol','group']]){const el=$(id);el.replaceChildren();if(key==='group')el.add(new Option(t('不分組（Point）'),''));for(const h of raw.headers)el.add(new Option(h,h));el.value=columns[key];}
 analysisController?.datasetChanged();$('fileLabel').textContent=filename;$('demoNote').hidden=!demo;applyColumns();if(!demo&&state.valid.length){setBounds(dataBounds(state.valid,.2));$('region').value='points';}else if(demo){$('fileLabel').textContent=tx('demoBadge',{n:state.groups.length});$('region').value='world';setBounds(REGIONS.world);}codegenController?.datasetChanged();}
function applyColumns(){try{const {valid,invalid}=normalizeRows(state.raw,state.columns);validationError='';state.valid=valid;state.invalid=invalid;const groups=[...new Set(valid.map(p=>p.group))].sort((a,b)=>a.localeCompare(b));const old=state.colors,oldShapes=state.shapes;state.groups=groups;state.displayNames=Object.fromEntries(groups.filter(g=>Object.hasOwn(state.displayNames,g)).map(g=>[g,state.displayNames[g]]));state.shapes=Object.fromEntries(groups.map(g=>[g,markerShape(oldShapes,g)]));state.colors=Object.fromEntries(groups.map((g,i)=>[g,(Object.hasOwn(old,g)?old[g]:colorFor(i))]));state.selected=new Set(groups);state.page=0;refreshValidation();$('validation').classList.toggle('warn',invalid.length>0||!valid.length);$('invalidBtn').hidden=!invalid.length;renderGroups();updateSites();}catch(e){state.valid=[];state.invalid=[];state.groups=[];state.selected=new Set();validationError=e.message;refreshValidation();$('validation').classList.add('warn');$('invalidBtn').hidden=true;renderGroups();updateSites();toast(e.message);}}
function renderGroups(){const root=$('groupList');root.replaceChildren();const selection=$('groupSelection');selection.replaceChildren();const counts=new Map();for(const p of state.valid)counts.set(p.group,(counts.get(p.group)||0)+1);state.groups.forEach((group,i)=>{const row=document.createElement('div');row.className='group-row';const check=document.createElement('input');check.type='checkbox';check.checked=state.selected.has(group);check.id=`group-${i}`;check.addEventListener('change',()=>{if(check.checked)state.selected.add(group);else state.selected.delete(group);state.page=0;updateSites();renderGroups();});const color=document.createElement('input');color.type='color';color.value=state.colors[group];color.setAttribute('aria-label',tx('color',{group}));color.addEventListener('input',()=>{state.colors[group]=color.value;scheduleDraw();});const label=document.createElement('label');label.htmlFor=check.id;label.textContent=group;label.title=group;const count=document.createElement('span');count.className='count';count.textContent=counts.get(group);const shape=document.createElement('select');shape.className='group-shape';shape.setAttribute('aria-label',tx('markerShape',{group}));for(const name of MARKER_SHAPES)shape.add(new Option(t(MARKER_LABELS[name]),name));shape.value=markerShape(state.shapes,group);shape.addEventListener('change',()=>{if(MARKER_SHAPES.includes(shape.value)){state.shapes[group]=shape.value;scheduleDraw();}});const preview=document.createElement('span');preview.className='shape-preview';preview.innerHTML=markerSVG(shape.value,state.colors[group]);shape.addEventListener('change',()=>{preview.innerHTML=markerSVG(shape.value,state.colors[group]);});color.addEventListener('input',()=>{preview.innerHTML=markerSVG(shape.value,color.value);});row.append(check,color,label,count,shape,preview);root.append(row);const entry=document.createElement('label');entry.className='selection-row';const toggle=document.createElement('input');toggle.type='checkbox';toggle.checked=state.selected.has(group);toggle.setAttribute('aria-label',group);toggle.addEventListener('change',()=>{if(toggle.checked)state.selected.add(group);else state.selected.delete(group);state.page=0;updateSites();renderGroups();});const name=document.createElement('span');name.textContent=group;const total=document.createElement('span');total.className='count';total.textContent=counts.get(group);entry.append(toggle,name,total);selection.append(entry);});}
async function readFile(file){const version=++fileReadVersion;try{if(!/\.csv$/i.test(file.name))throw Error('CSV files only.');let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());}catch{throw Error('Save the file as UTF-8 CSV and try again.');}const raw=parseCSV(text);if(version!==fileReadVersion)return;installData(raw,file.name,false);toast(tx('imported',{file:file.name}));}catch(e){if(version!==fileReadVersion)return;toast(tx('importFailed',{reason:t(e.message)}));}}
$('csvFile').addEventListener('change',e=>{if(e.target.files[0])readFile(e.target.files[0]);e.target.value='';});
for(const event of ['dragenter','dragover'])$('dropzone').addEventListener(event,e=>{e.preventDefault();$('dropzone').classList.add('dragging');});for(const event of ['dragleave','drop'])$('dropzone').addEventListener(event,e=>{e.preventDefault();$('dropzone').classList.remove('dragging');});$('dropzone').addEventListener('drop',e=>{if(e.dataTransfer.files[0])readFile(e.dataTransfer.files[0]);});
