function validateBounds(bounds){if(!Array.isArray(bounds)||bounds.length!==4||!bounds.every(Number.isFinite))throw Error('請輸入有效範圍：經度介於 −180° 與 180° 且東西界不同；南界須小於北界，緯度介於 −85° 與 85°。');const [west,south,east,north]=bounds;if(west===east||west-east===360||south>=north||west< -180||west>180||east< -180||east>180||south< -85||north>85)throw Error('請輸入有效範圍：經度介於 −180° 與 180° 且東西界不同；南界須小於北界，緯度介於 −85° 與 85°。');return bounds;}
function setBounds(bounds,centerLongitude){validateBounds(bounds);const [west,south,east,north]=bounds;state.referenceBounds=[...bounds];const p=layout(state.settings);state.camera=defaultCamera(state.settings,bounds,centerLongitude??(east-west>=350?state.settings.worldCenter:undefined));for(const [id,v] of Object.entries({west,south,east,north}))$(id).value=v.toFixed(5);scheduleDraw();}
function applyRegion(){try{const r=$('region').value;if(Object.hasOwn(REGIONS,r))setBounds(REGIONS[r]);else if(r==='points')setBounds(dataBounds(activePoints(),.15));else setBounds(['west','south','east','north'].map(id=>Number($(id).value)));}catch(e){toast(e.message);}}
$('region').addEventListener('change',applyRegion);$('applyBounds').addEventListener('click',()=>{try{if(['west','south','east','north'].some(id=>$(id).value.trim()===''))throw Error('請填寫全部範圍。');setBounds(['west','south','east','north'].map(id=>Number($(id).value)));$('region').value='custom';}catch(e){toast(e.message);}});
const limits={contourInterval:[100,1000],provinceWidth:[.2,1.5],legendColumns:[1,3],legendFont:[6,24],legendSymbol:[2,12],legendX:[0,100],legendY:[0,100],siteLabelSize:[7,24],pageWidth:[5,60],pageHeight:[5,60],shadow:[0,.6],direction:[0,360],angle:[1,90],terrainZoom:[1,12],digits:[2,6],radius:[3,18]};
for(const key of Object.keys(defaults)){const el=$(key);if(!el||key==='pageWidth'||key==='pageHeight')continue;el.addEventListener(el.type==='range'?'input':'change',()=>{let val=el.type==='checkbox'?el.checked:typeof defaults[key]==='number'?Number(el.value):el.value;if(limits[key]){if(el.value.trim()===''||!Number.isFinite(val)){el.value=state.settings[key];return;}val=Math.max(limits[key][0],Math.min(limits[key][1],val));el.value=val;}state.settings[key]=val;if(key==='projection')setBounds(state.referenceBounds);syncLegendControls();updateSites();});}
$('minimalBtn').addEventListener('click',()=>{for(const key of ['countries','countryLabels','provinces','provinceLabels','frame','grid','northArrow','scaleBar','legend']){state.settings[key]=false;$(key).checked=false;}scheduleDraw();});
function setView(view){const table=view===true||view==='table',elevation=view==='elevation',code=view==='code';$('canvasTopline').hidden=code;$('legendStudioBtn').hidden=code;if(code)legendEditor?.close();$('codeView').hidden=!code;$('codeTab').classList.toggle('active',code);$('elevationView').hidden=!elevation;$('elevationTab').classList.toggle('active',elevation);if(elevation)analysisController?.refresh(true);if(code)codegenController?.refresh();$('mapView').hidden=table||elevation||code;$('tableView').hidden=!table;$('mapTab').classList.toggle('active',!table&&!elevation&&!code);$('tableTab').classList.toggle('active',table);if(table)updateTable();}
