function updateTable(){if(!state.raw)return;const data=activePoints(),per=30,pages=Math.max(1,Math.ceil(data.length/per));state.page=Math.min(state.page,pages-1);$('tableCount').textContent=tx('selectedRows',{selected:data.length.toLocaleString(),total:state.valid.length.toLocaleString()});$('tableHead').replaceChildren();const tr=document.createElement('tr');for(const h of [t('來源列'),...state.raw.headers]){const th=document.createElement('th');th.textContent=h;tr.append(th);}$('tableHead').append(tr);$('tableBody').replaceChildren();for(const p of data.slice(state.page*per,(state.page+1)*per)){const row=document.createElement('tr');for(const value of [p.line,...p.row]){const td=document.createElement('td');td.textContent=value;row.append(td);}$('tableBody').append(row);}$('pageInfo').textContent=`${state.page+1} / ${pages}`;$('prevPage').disabled=state.page===0;$('nextPage').disabled=state.page>=pages-1;}
$('prevPage').addEventListener('click',()=>{state.page--;updateTable();});$('nextPage').addEventListener('click',()=>{state.page++;updateTable();});$('downloadData').addEventListener('click',()=>download(new Blob([csvEncode([state.raw.headers,...activePoints().map(p=>p.row)])],{type:'text/csv;charset=utf-8'}),'filtered_records.csv'));
const canvas=$('map');let dragging=null;
const logical=e=>pointerPosition(e.clientX,e.clientY,canvas.getBoundingClientRect(),state.settings);
function zoom(factor,anchor=null){const p=layout(state.settings),[x,y]=anchor||[p.x+p.w/2,p.y+p.h/2];if(projected(state.settings,state.camera,p)){const q=projector(state.settings,state.camera,p).invert(x,y);state.camera=anchorCamera(state.settings,state.camera,p,q,[x,y],Math.max(1,Math.min(17,state.camera.zoom+factor)));scheduleDraw();return;}const before=256*2**state.camera.zoom,zoom=Math.max(1,Math.min(17,state.camera.zoom+factor)),after=256*2**zoom;state.camera.x+=(x-p.x-p.w/2)*(1/before-1/after);state.camera.y+=(y-p.y-p.h/2)*(1/before-1/after);state.camera.zoom=zoom;clampCamera();scheduleDraw();}
function clampCamera(){const p=layout(state.settings);if(!projected(state.settings,state.camera,p)){state.camera=boundedMercatorCamera(state.camera,p);return;}state.camera.x=wrapUnit(state.camera.x);state.camera.y=Math.max(0,Math.min(1,state.camera.y));}
let cropMode=false,cropStart=null,cropRect=null;
function finishCrop(){cropMode=false;cropStart=null;cropRect=null;$('cropOverlay').hidden=true;$('cropActions').hidden=true;$('cropStart').setAttribute('aria-pressed','false');canvas.style.cursor='';}
function showCrop(){if(!cropRect)return;const f=pageSize(state.settings),el=$('cropOverlay');el.hidden=false;el.style.left=(cropRect.x/f.width*100)+'%';el.style.top=(cropRect.y/f.height*100)+'%';el.style.width=(cropRect.w/f.width*100)+'%';el.style.height=(cropRect.h/f.height*100)+'%';$('cropApply').disabled=cropRect.w<30||cropRect.h<30;}
$('cropStart').addEventListener('click',()=>{if(cropMode){finishCrop();return;}cropMode=true;$('cropStart').setAttribute('aria-pressed','true');$('cropActions').hidden=false;$('cropApply').disabled=true;canvas.style.cursor='crosshair';$('tooltip').hidden=true;});
