$('cropApply').addEventListener('click',()=>{if(!cropRect||cropRect.w<30||cropRect.h<30)return;const p=layout(state.settings),rect=cropRect,points=[];for(let j=0;j<=8;j++)for(let i=0;i<=8;i++){const [lon,lat]=inversePosition(rect.x+rect.w*i/8,rect.y+rect.h*j/8,state.camera,p,state.settings);if(Number.isFinite(lon+lat)&&Math.abs(lat)<=85)points.push({lon,lat});}if(points.length<2){toast('請在有效地圖範圍內框選。');return;}const bounds=dataBounds(points,0);state.settings=cropSettings(state.settings,rect,layout);syncPageControls();setBounds(bounds);$('region').value='custom';finishCrop();});
