function prepareConfig(cfg,raw=state.raw){
  if(!cfg||cfg.application!=='TaiwanBioTopoMaps'||cfg.version!==1)throw Error('不是支援的地圖設定檔。');
  if(cfg.shapes!==undefined&&(!cfg.shapes||typeof cfg.shapes!=='object'||Array.isArray(cfg.shapes)||Object.values(cfg.shapes).some(v=>![...MARKER_SHAPES,...LEGACY_MARKER_SHAPES].includes(v))))throw Error('符號設定錯誤。');
  cfg={...cfg,shapes:cfg.shapes&&Object.fromEntries(Object.entries(cfg.shapes).map(([g,v])=>[g,LEGACY_MARKER_SHAPES.includes(v)?'circle':v]))};
  const edits=validateLegendEdits(cfg.legendEdits),names=validateDisplayNames(cfg.displayNames),analysis=validateAnalysis(cfg.analysis);if(analysis.column&&!raw.headers.includes(analysis.column))throw Error('設定檔欄位與目前 CSV 不符，請先匯入相同資料。');
  const settings={...defaults};
  for(const key of Object.keys(defaults)){
   // Older projects could disable the detailed coast. Migrate them to the current default.
   if(key==='coastDetail')continue;
   const v=cfg.settings?.[key];if(v===undefined)continue;
   if(typeof v!==typeof defaults[key]||typeof v==='number'&&(!Number.isFinite(v)||(limits[key]&&(v<limits[key][0]||v>limits[key][1]))))throw Error('設定數值超出範圍。');
   if(key==='pieMode'&&!['presence','count'].includes(v))throw Error('圓餅比例設定錯誤。');settings[key]=v;
  }
  if(!['species','groups'].includes(settings.legendTitle)||!LEGEND_POSITIONS.includes(settings.legendPosition)||!Number.isInteger(settings.legendColumns)||!['fast','auto','detail','maximum'].includes(settings.terrainQuality))throw Error('設定數值超出範圍。');
  if(![100,200,250,500,1000].includes(settings.contourInterval))throw Error('設定數值超出範圍。');
  pageSize(settings);
  if(settings.basemap==='topo')settings.basemap='osm';
  if(!BASEMAPS.includes(settings.basemap)||![0,150,PACIFIC_CENTER].includes(settings.worldCenter)||!PROJECTIONS.includes(settings.projection))throw Error('設定數值超出範圍。');
  if(!Number.isInteger(settings.terrainZoom)||settings.terrainZoom<7||settings.terrainZoom>12||!Number.isInteger(settings.digits))throw Error('圖磚層級或座標精度錯誤。');
  const cam=cfg.camera;
  if(!cam||![cam.x,cam.y,cam.zoom].every(Number.isFinite)||cam.x<0||cam.x>1||cam.y<0||cam.y>1||cam.zoom<1||cam.zoom>17)throw Error('地圖視角設定錯誤。');
  const bounds=[...validateBounds(cfg.referenceBounds??state.referenceBounds)],columns={...(cfg.columns??state.columns)};
  if(!raw.headers.includes(columns.lon)||!raw.headers.includes(columns.lat)||(columns.group!==''&&!raw.headers.includes(columns.group)))throw Error('設定檔欄位與目前 CSV 不符，請先匯入相同資料。');
  normalizeRows(raw,columns);
  if(cfg.selected!==undefined&&(!Array.isArray(cfg.selected)||cfg.selected.some(g=>typeof g!=='string')))throw Error('不是支援的地圖設定檔。');
  if(cfg.settings?.freshwater===undefined)
   settings.freshwater=cfg.settings?.rivers===true||cfg.settings?.lakes===true;
  return {cfg,settings,bounds,columns,cam,edits,names,analysis};
}
function applyConfig({cfg,settings,bounds,columns,cam,edits,names,analysis}){
  // Commit only after every setting, extent and column mapping has validated.
  analysisController?.stop();
  state.columns=columns;for(const [id,key] of [['lonCol','lon'],['latCol','lat'],['groupCol','group']])$(id).value=columns[key];applyColumns();
  state.analysis=analysis;state.settings=settings;state.legendEdits=edits;state.displayNames=names;
  for(const [key,v] of Object.entries(settings))if($(key)){$(key).type==='checkbox'?$(key).checked=v:$(key).value=v;}
  setBounds(bounds);$('region').value=Array.from($('region').options).find(({value})=>REGIONS[value]?.every((v,i)=>v===bounds[i]))?.value||'custom';state.camera={x:cam.x,y:cam.y,zoom:cam.zoom};
  for(const group of state.groups)if(/^#[0-9a-f]{6}$/i.test(cfg.colors?.[group]))state.colors[group]=cfg.colors[group];
  state.shapes=Object.fromEntries(state.groups.map(g=>[g,markerShape(cfg.shapes,g)]));
  if(Array.isArray(cfg.selected))state.selected=new Set(cfg.selected.filter(g=>state.groups.includes(g)));
  if(Object.hasOwn(LANGUAGES,cfg.language))setLanguage(cfg.language);
  codegenController?.restored();refreshLanguage();updateSites();
}
