async function exportMap(batch=false){if(busy)return;if(!ready){toast('行政界線尚未載入。');return;}if(!activePoints().length){toast('請至少選擇一個有有效座標的物種。');return;}const status=renderer.status(state);if(!status.ready){toast(status.detailFailed?'詳細地理圖層載入失敗，請重新載入。':status.detailPending?'詳細地理圖層尚未載入完成。':status.streetFailed?'OpenStreetMap 街道底圖載入失敗，請重新載入或切回地形底圖。':status.streetPending?'街道底圖載入中，完成後即可匯出。':status.waterFailed?'水域圖層載入失敗，請重新載入或關閉水域圖層。':status.waterPending?'水域圖層正在載入，完成後即可匯出。':status.adminFailed?'省州界線載入失敗，請按重新載入後再匯出。':status.adminPending?'省州界線正在載入，完成後即可匯出。':status.failed?'海拔圖磚載入失敗。請重新載入，或在樣式中關閉海拔底圖。':'目前範圍的海拔仍在載入，完成後即可匯出。');scheduleDraw();return;}busy=true;const snapshot={...state,interacting:false,settings:{...state.settings},camera:{...state.camera},colors:{...state.colors},shapes:{...state.shapes},legendEdits:structuredClone(state.legendEdits),displayNames:{...state.displayNames},analysis:structuredClone(state.analysis),groups:[...state.groups],selected:new Set(state.selected),columns:{...state.columns},referenceBounds:[...state.referenceBounds],sites:[...state.sites]};const points=[...activePoints()],selected=[...state.selected];$('exportBtn').disabled=$('batchBtn').disabled=$('topExport').disabled=true;const format=$('format').value,width=Number($('exportWidth').value),prefix=safeName($('prefix').value);try{const fontWork=prepareLegendFonts(snapshot);if(fontWork)await fontWork;const make=async sites=>{const c=document.createElement('canvas'),scene={...snapshot,sites};const result=renderer.render(scene,{canvas:c,width,svg:format==='svg'}),metadata=mapSource(snapshot)+`; Demo=${snapshot.demo}; settings=${JSON.stringify(snapshot.settings)}; groups=${JSON.stringify(snapshot.groups)}; markerShapes=${JSON.stringify(snapshot.shapes)}; legendEdits=${JSON.stringify(snapshot.legendEdits)}; displayNames=${JSON.stringify(snapshot.displayNames)}`;if(format==='svg')return new Blob([result.svg],{type:'image/svg+xml;charset=utf-8'});const page=pageSize(snapshot.settings);if(format==='pdf')return pdfBlob(c,metadata,page);return await pngBlob(c,metadata,page);};if(!batch){$('exportStatus').textContent=t('正在繪製圖檔…');await nextFrame();const blob=await make(snapshot.sites);download(blob,`${prefix}.${format}`);$('exportStatus').textContent=tx('exported',{file:`${prefix}.${format}`});}else{const files=[],root=prefix+'_figures',all=snapshot.sites;let i=0;const jobs=[{name:'All',sites:all},...selected.map(g=>({name:g,sites:withSiteIds(groupSites(points.filter(p=>p.group===g),snapshot.settings.digits,snapshot.settings.pieMode,snapshot.settings.pies),snapshot.catalog,snapshot.settings.pies)}))];const names=new Set();for(const job of jobs){$('exportStatus').textContent=tx('rendering',{i:++i,n:jobs.length,name:job.name});await nextFrame();const name=uniqueName(job.name,names);files.push({name:`${root}/${name}/${prefix}_${name}.${format}`,data:await make(job.sites)},{name:`${root}/${name}/${prefix}_${name}_sites.csv`,data:siteTable(job.sites)});}files.push({name:`${root}/SOURCES.txt`,data:mapSource(snapshot)+`\nDemonstration data: ${snapshot.demo}\nSVG land and ocean terrain are embedded rasters; contours, rivers and lakes are vectors. PDF is a raster image.\nCoordinate grouping uses decimal rounding (ties to even), not a distance radius.\n`},{name:`${root}/settings.json`,data:JSON.stringify(config(snapshot),null,2)});$('exportStatus').textContent=t('正在整理 ZIP…');await nextFrame();download(await zipBlob(files),`${prefix}_figures.zip`);$('exportStatus').textContent=tx('batchDone',{n:selected.length});}toast('圖檔已準備好。');}catch(e){toast(tx('exportFailed',{reason:t(e.message)}));$('exportStatus').textContent=t('匯出失敗；可先降低解析度再試。');}finally{busy=false;$('exportBtn').disabled=$('batchBtn').disabled=$('topExport').disabled=false;scheduleDraw();}}
