function refreshViewport(){
 const v=viewportSummary(state);
 $('viewportCount').textContent=tx('viewportSummary',{total:v.total,inside:v.inside,outside:v.outside,sites:v.sitesInside});
 $('fitVisible').hidden=v.outside===0;$('fitVisible').textContent=t('顯示全部樣點');
 $('undoEdit').textContent=t('↶ 復原');$('redoEdit').textContent=t('↷ 重做');
}
$('fitVisible').addEventListener('click',()=>$('fitBtn').click());
const historyRead=()=>({settings:state.settings,camera:state.camera,referenceBounds:state.referenceBounds,colors:state.colors,shapes:state.shapes,legendEdits:state.legendEdits,displayNames:state.displayNames,selected:[...state.selected],region:$('region').value});
let historyData=state.raw,historyColumns=JSON.stringify(state.columns),historyGeneration=0,historyGroup=null;
historyController=createHistory(historyRead,snapshot=>{
 const {selected,region,...values}=snapshot;Object.assign(state,values);state.selected=new Set(selected);
 for(const [key,v] of Object.entries(state.settings)){const el=$(key);if(el)el.type==='checkbox'?el.checked=v:el.value=v;}
 $('region').value=region;['west','south','east','north'].forEach((id,i)=>$(id).value=state.referenceBounds[i].toFixed(5));
 renderGroups();syncPageControls();syncLegendControls();updateSites();
},{dataset:()=>{const columns=JSON.stringify(state.columns);if(historyData!==state.raw||historyColumns!==columns){historyData=state.raw;historyColumns=columns;historyGeneration++;}return historyGeneration;},group:()=>historyGroup,onChange:(undo,redo)=>{$('undoEdit').disabled=!undo;$('redoEdit').disabled=!redo;}});
$('undoEdit').addEventListener('click',()=>historyController.undo());$('redoEdit').addEventListener('click',()=>historyController.redo());
// A drag is one history step; rapid slider/colour input is coalesced.
document.addEventListener?.('input',e=>{historyGroup=['range','color'].includes(e.target.type)?e.target:null;},true);
document.addEventListener?.('change',()=>{historyGroup=null;},true);
document.addEventListener?.('pointerdown',()=>{historyController.capture();historyGroup=null;historyHolding=true;},true);
for(const event of ['pointerup','pointercancel'])document.addEventListener?.(event,()=>{historyHolding=false;historyController.schedule();},true);
document.addEventListener?.('keydown',e=>{
 if(!(e.ctrlKey||e.metaKey)||e.altKey||e.target.closest?.('input,textarea,select,[contenteditable="true"]'))return;
 if(e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?historyController.redo():historyController.undo();}
 else if(e.ctrlKey&&e.key.toLowerCase()==='y'){e.preventDefault();historyController.redo();}
});
refreshViewport();
